  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Attempts to place the current pipe from queue at specified position.
   * Algorithm:
   *   targetCol = col - 'A' + 1   // convert letter to internal column index
   *   pipe = pipeQueue.peek()
   *   if pipe is null then return false
   *   if map.tryPlacePipe(row, targetCol, pipe) then
   *       pipeQueue.consume()
   *       cellStack.push(map.getCell(row, targetCol) as FillableCell)
   *       numOfSteps = numOfSteps + 1
   *       return true
   *   else
   *       return false
   * Related Features: map, pipeQueue, cellStack, numOfSteps fields
   * Related Classes: Map, PipeQueue, CellStack, Pipe, FillableCell
   * Input: row - int (1 to rows-2), col - char ('A' to corresponding last column)
   * Output: boolean - true if placement succeeded, false otherwise
   * Pre-condition: row and col are valid player-facing coordinates
   * Post-condition: If successful: pipe placed on board, queue consumed, placement recorded, steps incremented.
   *                 If failed: no changes to board or queue.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean placePipe(final int row, final char col)
  {
    int targetCol = col - 'A' + 1;
    Pipe pipe = getPipeQueue().peek();
    if (pipe == null) {
      return false;
    }
    if (getMap().tryPlacePipe(row, targetCol, pipe)) {
      getPipeQueue().consume();
      getCellStack().push((FillableCell) getMap().getCell(row - 1, targetCol - 1));
      setNumOfSteps(getNumOfSteps() + 1);
      return true;
    } else {
      return false;
    }
  }

